// ============================================================
// HMAC-SHA256 Signature Verification
// Mirrors the logic in backend/app/events/signing.py
// ============================================================

const crypto = require('crypto');

const HMAC_SECRET   = $env['N8N_WEBHOOK_HMAC_SECRET'];
const MAX_SKEW_SECS = 300; // must match N8N_TIMESTAMP_TOLERANCE_SECONDS

const item = $input.first();
const headers = item.json.headers || {};

// 1. Extract headers (header names are lowercased by n8n)
const sigHeader = headers['x-eduai-signature-256'] || '';
const tsHeader  = headers['x-eduai-timestamp']     || '';
const idempKey  = headers['x-eduai-idempotency-key'] || '';

// 2. Timestamp freshness check
const nowSecs = Math.floor(Date.now() / 1000);
const tsSecs  = parseInt(tsHeader, 10);
if (isNaN(tsSecs) || Math.abs(nowSecs - tsSecs) > MAX_SKEW_SECS) {
  throw new Error(`Timestamp rejected: skew=${nowSecs - tsSecs}s, max=${MAX_SKEW_SECS}s`);
}

// 3. Signature verification — compare over raw body bytes
const rawBody = item.json.rawBody || JSON.stringify(item.json.body);
const expected = 'sha256=' + crypto
  .createHmac('sha256', HMAC_SECRET)
  .update(rawBody, 'utf8')
  .digest('hex');

// constant-time comparison
const sigBuf = Buffer.from(sigHeader);
const expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Signature verification failed');
}

// 4. Parse and forward the verified body
let body;
try {
  body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
} catch (e) {
  throw new Error('Invalid JSON body: ' + e.message);
}

// Attach idempotency key for downstream deduplication
return [{ json: { ...body, _idempotency_key: idempKey, _verified: true } }];

// ============================================================
// Idempotency Gate
// Uses n8n's static data to remember processed event_ids.
// In production replace with a Redis SET NX call via HTTP Request node.
// ============================================================

const item = $input.first();
const eventId = item.json.event_id || '';

if (!eventId) {
  throw new Error('event_id is required for idempotency');
}

// Retrieve processed set from workflow static data
const workflowStaticData = $getWorkflowStaticData('global');
if (!workflowStaticData.processedEvents) {
  workflowStaticData.processedEvents = {};
}

if (workflowStaticData.processedEvents[eventId]) {
  // Already processed — short-circuit with a 200 so the emitter doesn't retry
  return [{ json: { duplicate: true, event_id: eventId, status: 'already_processed' } }];
}

// Mark as processed (TTL-based eviction not available in static data;
// rotate the map when it exceeds 10000 entries to bound memory)
const keys = Object.keys(workflowStaticData.processedEvents);
if (keys.length > 10000) {
  // Drop the oldest 2000 entries (insertion order)
  keys.slice(0, 2000).forEach(k => delete workflowStaticData.processedEvents[k]);
}
workflowStaticData.processedEvents[eventId] = Date.now();

return [{ json: { ...item.json, duplicate: false } }];

// ============================================================
// Structured Event Log
// In production: forward to your logging pipeline (Loki, Datadog, etc.)
// via an HTTP Request node instead of console.log.
// ============================================================

const item = $input.first();
const payload = item.json.payload || {};

const logEntry = {
  level: 'info',
  event_id:       item.json.event_id,
  event_type:     item.json.event_type,
  schema_version: item.json.schema_version,
  correlation_id: item.json.correlation_id,
  timestamp:      item.json.timestamp,
  received_at:    new Date().toISOString(),
  file_id:        payload.file_id,
  user_id:        payload.user_id,
  role:           payload.role,
  file_name:      payload.file_name,
  file_size_bytes: payload.file_size_bytes,
  mime_type:      payload.mime_type,
  submission_id:  payload.submission_id,
};

console.log(JSON.stringify(logEntry));

return [{ json: { log_entry: logEntry, processed: true } }];
